biasedBins = {
  const w = 0.005, ncpHalfPower = 1.96, moved = 0.3
  const b = d3.range(20).map(i =&gt; {
    const lo = i * w, hi = (i + 1) * w
    const unbiased = 0.5 * w + 0.5 * (pCdfAt(hi, ncpHalfPower) - pCdfAt(lo, ncpHalfPower))
    return {lo, hi, unbiased, biased: unbiased, sig: hi &lt;= 0.05 + 1e-9}
  })
  const removed = d3.sum(b.slice(10), d =&gt; d.unbiased * moved)
  b.slice(10).forEach(d =&gt; d.biased = d.unbiased * (1 - moved))
  b[8].biased += removed / 3
  b[9].biased += removed * 2 / 3
  return b
